const recordsA = $('Fetch Their Catalog').first().json.products;
const recordsB = $('Fetch Your Catalog').first().json.products;
const currencyA = $('Read tentree currency').first().json.currency;
const currencyB = $('Read Allbirds currency').first().json.currency;
if (!/^[A-Z]{3}$/.test(currencyA || '') || !/^[A-Z]{3}$/.test(currencyB || '')) throw new Error('A storefront did not report a valid currency.');
const capturedAt = new Date().toISOString();
