 const skus = new Map();
 for (const p of products) for (const v of p.variants || []) { if (v.sku) skus.set(v.sku,(skus.get(v.sku)||0)+1); }
 for (const p of products) {
  const vs = p.variants || []; const flags=[];
  const missingSku=vs.filter(v=>!String(v.sku||'').trim()).length;
  const duplicateSku=vs.filter(v=>v.sku && skus.get(v.sku)>1).length;
  const missingAlt=(p.images||[]).filter(i=>!String(i.alt||'').trim()).length;
  if (missingSku) flags.push(missingSku+' variant(s): SKU absent in public feed');
  if (duplicateSku) flags.push(duplicateSku+' variant(s): repeated SKU in captured feed');
  if (!String(p.product_type||'').trim()) flags.push('Product type absent in public feed');
  if (!String(p.body_html||'').replace(/<[^>]*>/g,'').trim()) flags.push('Description absent in public feed');
  if (!(p.images||[]).length) flags.push('Images absent in public feed');
  if (missingAlt) flags.push(missingAlt+' image(s): alt text absent in public feed');
  const badPrices=vs.filter(v=>!Number.isFinite(Number(v.price))||Number(v.price)<=0).length;
  if (badPrices) flags.push(badPrices+' variant(s): price requires review');
  const priced=vs.map(v=>Number(v.price)).filter(v=>Number.isFinite(v)&&v>0);
  const url='https://'+store+'/products/'+p.handle;
  const row={store,productId:String(p.id),title:p.title,handle:p.handle,url,productType:p.product_type||'',currency,minPrice:priced.length?Math.min(...priced):null,maxPrice:priced.length?Math.max(...priced):null,variantCount:vs.length,availableVariants:vs.filter(v=>v.available).length,imageCount:(p.images||[]).length,missingAlt,missingSku,duplicateSku,reviewFlags:flags,status:flags.length?'Review public fields':'No flags in checked fields'};
  audit.push(row);
  for(const v of vs) variants.push({store,productId:String(p.id),productTitle:p.title,variantId:String(v.id),variantTitle:v.title,sku:v.sku||'',price:Number(v.price),currency,available:Boolean(v.available),option1:v.option1,option2:v.option2,option3:v.option3,sourceUrl:url});
 }
}
const baseline=$('Read previous verified capture').first().json;
const previous=baseline.capturedAt ? baseline : null;const prices={};const changes=[];
for(const p of audit){const key=p.store+'|'+p.productId;prices[key]={minPrice:p.minPrice,currency:p.currency};const old=previous?.prices?.[key];if(old && old.currency===p.currency && old.minPrice!==p.minPrice)changes.push({title:p.title,url:p.url,previous:old.minPrice,current:p.minPrice,currency:p.currency});}
// The preview server atomically persists the complete successful response as the next baseline.
return [{json:{engine:'n8n',workflowId:'publicCatalogReview001',executionId:String($execution.id),capturedAt,sourceTemplate:{id:18502,creator:'Daniel Shashko',url:'https://n8n.io/workflows/18502-track-competitor-shopify-launches-and-pricing-with-bright-data-and-gmail/',adaptation:'Two catalog parser nodes preserved unchanged. Direct public GET replaces Bright Data; manual trigger, snapshot comparison and catalog QA replace Gmail delivery and Data Tables.'},scope:'First 12 products from each of two public storefront feeds. Independent research; neither brand is a client. Public feed gaps are review prompts, not confirmed storefront defects. No private inventory quantities, sales data, or customer records accessed.',sources:[{brand:'tentree',url:'https://www.tentree.com/products.json?limit=12',currencyUrl:'https://www.tentree.com/cart.js',currency:currencyA},{brand:'Allbirds',url:'https://www.allbirds.com/products.json?limit=12',currencyUrl:'https://www.allbirds.com/cart.js',currency:currencyB}],summary:{products:audit.length,variants:variants.length,productsForReview:audit.filter(p=>p.reviewFlags.length).length,missingSkuVariants:audit.reduce((s,p)=>s+p.missingSku,0),imagesWithoutAlt:audit.reduce((s,p)=>s+p.missingAlt,0),priceChanges:changes.length},comparison:{baselineAt:previous?.capturedAt||null,note:previous?'Compared only matching product IDs in the same currency against the previous local successful capture.':'First capture establishes a baseline. No historical price-change claim.',changes},audit,variants,normalized}}];
